// Measures the steps behind importing and selecting a large mesh (NFR-004-02,
// NFR-004-03). Not part of ctest: run it on a Release build with the large
// files generated by
//   python tests/data/gmsh/generate_test_meshes.py --large <folder>
//
// Usage: bench_mesh_scene <file.msh>

#include <fem/core/mesh.hpp>
#include <fem/core/mesh_surface.hpp>
#include <fem/io/gmsh_reader.hpp>
#include <fem/render/camera.hpp>
#include <fem/render/mesh_picker.hpp>
#include <fem/render/mesh_scene.hpp>

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <memory>
#include <span>

namespace {

using Clock = std::chrono::steady_clock;

double secondsSince(Clock::time_point start)
{
    return std::chrono::duration<double>(Clock::now() - start).count();
}

int run(int argc, char** argv)
{
    const std::span<char* const> args(argv, static_cast<std::size_t>(argc));
    if (args.size() != 2) {
        std::fputs("usage: bench_mesh_scene <file.msh>\n", stderr);
        return EXIT_FAILURE;
    }

    auto start = Clock::now();
    auto read = fem::io::readGmsh(std::filesystem::path(args[1]));
    if (!read) {
        std::fprintf(stderr, "%s\n", read.error().message.c_str());
        return EXIT_FAILURE;
    }
    std::printf("read            %.3f s\n", secondsSince(start));
    auto mesh = std::make_shared<const fem::core::Mesh>(std::move(read->mesh));

    start = Clock::now();
    const fem::core::MeshSurface surface = fem::core::extractSurface(*mesh);
    std::printf("extractSurface  %.3f s (%zu solid faces)\n", secondsSince(start),
                surface.faces3d.size());

    start = Clock::now();
    const auto scene = fem::render::buildMeshScene(mesh);
    std::printf("buildMeshScene  %.3f s (includes extractSurface)\n", secondsSince(start));

    fem::render::Camera camera;
    constexpr int kWidth = 1920;
    constexpr int kHeight = 1080;
    camera.setViewportSize(kWidth, kHeight);
    const fem::core::BoundingBox box = mesh->boundingBox();
    camera.fit({.min = box.min, .max = box.max});

    const fem::render::MeshPicker picker(scene);
    const fem::render::DisplayOptions display;
    const fem::render::Vec2 centre(kWidth / 2.0, kHeight / 2.0);

    start = Clock::now();
    const auto clicked = picker.pick(camera, centre, fem::render::SelectionFilter{}, display, 5.0);
    std::printf("click           %.3f s (%s)\n", secondsSince(start), clicked ? "hit" : "miss");

    fem::render::SelectionFilter all;
    all.enabled = {true, true, true, true};
    start = Clock::now();
    const auto clickedAll = picker.pick(camera, centre, all, display, 5.0);
    std::printf("click, all kinds %.3f s (%s)\n", secondsSince(start), clickedAll ? "hit" : "miss");

    // A window over the left half of the screen, then a crossing.
    const fem::render::PickRect window{.from = {10.0, 10.0}, .to = {kWidth / 2.0, kHeight - 10.0}};
    start = Clock::now();
    const auto inWindow = picker.pickRect(camera, window, fem::render::SelectionFilter{}, display);
    std::printf("window          %.3f s (%zu elements)\n", secondsSince(start),
                inWindow[fem::render::SelectionKind::Element].size());

    const fem::render::PickRect crossing{.from = window.to, .to = window.from};
    start = Clock::now();
    const auto crossed = picker.pickRect(camera, crossing, all, display);
    std::printf("crossing, all   %.3f s (%zu elements, %zu nodes)\n", secondsSince(start),
                crossed[fem::render::SelectionKind::Element].size(),
                crossed[fem::render::SelectionKind::Node].size());

    start = Clock::now();
    const auto pivot = picker.visibleCenter(camera, display);
    std::printf("visibleCenter   %.3f s (%s)\n", secondsSince(start), pivot ? "found" : "none");
    return EXIT_SUCCESS;
}

} // namespace

int main(int argc, char* argv[])
{
    try {
        return run(argc, argv);
    } catch (const std::exception& error) {
        std::fprintf(stderr, "error: %s\n", error.what());
        return EXIT_FAILURE;
    }
}
